-- verify_staging.sql - READ-ONLY status of the STAGING database.
-- (The object-by-object comparison with production is db/schema/inventory_check.sql,
--  generated by scripts/staging/schema-inventory.mjs.)
begin read only;

\echo '== 1. Tables in public: row-level security and policy count (expect RLS on every table)'
select c.relname as table_name, c.relrowsecurity as rls_enabled,
       (select count(*) from pg_policies p where p.schemaname = 'public' and p.tablename = c.relname) as policies
from pg_class c join pg_namespace n on n.oid = c.relnamespace
where n.nspname = 'public' and c.relkind = 'r' order by c.relname;

\echo '== 2. P-022 migration columns on model_outputs (expect 5 rows)'
select column_name, data_type, is_nullable from information_schema.columns
where table_schema = 'public' and table_name = 'model_outputs'
  and column_name in ('engine_version','result_schema_version','periodicity','result_payload','inputs_snapshot')
order by column_name;

\echo '== 3. model_outputs primary key (expect output_id)'
select kcu.column_name as primary_key from information_schema.table_constraints tc
join information_schema.key_column_usage kcu on kcu.constraint_name = tc.constraint_name and kcu.table_schema = tc.table_schema
where tc.table_schema = 'public' and tc.table_name = 'model_outputs' and tc.constraint_type = 'PRIMARY KEY';

\echo '== 4. Rows (expect 0 except static_defaults reference data and synthetic test rows)'
select 'tenants' t, count(*) from public.tenants union all
select 'users', count(*) from public.users union all
select 'projects', count(*) from public.projects union all
select 'versions', count(*) from public.versions union all
select 'model_outputs', count(*) from public.model_outputs union all
select 'assumptions', count(*) from public.assumptions union all
select 'static_defaults', count(*) from public.static_defaults;

\echo '== 5. Auth users in staging (expect only synthetic staging test users)'
select count(*) as auth_users from auth.users;

rollback;
